import { Request, Response } from 'express';
import { GetStockLevelsUseCase } from '../application/GetStockLevelsUseCase';

export class ProductController {
  constructor(private getStockLevelsUseCase: GetStockLevelsUseCase) {}

  getStockLevels = (req: Request, res: Response): void => {
    try {
      const products = this.getStockLevelsUseCase.execute();
      res.status(200).json(products);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };
}

